        <article className="panel preview-table"><b>Customer Udhaar</b><div className="head"><span>Date</span><span>Customer</span><span>Amount</span></div>{["Ramesh Kumar","Sunita Devi","Amit Verma"].map((name,index)=><div key={name}><span>{26-index} Jul</span><strong>{name}</strong><span>₹{[1280,960,740][index]}</span></div>)}</article>
