    {!visible.length&&<p className="empty">No Udhaar record in this date range.</p>}
    {visible.length>0&&<div className="udhaar-totals"><span>Total Udhaar <b>{money(totals.amount)}</b></span><span>Total repaid <b>{money(totals.given)}</b></span><span>Total pending <b>{money(totals.pending)}</b></span></div>}
